const input = `



`;

// const input = `ULL
// RRDDD
// LURDL
// UUUUD`;

const splitInput = input.trim().split("\n");

let instructions = {
    "U": [-1, 0],
    "D": [1, 0],
    "L": [0, -1],
    "R": [0, 1]
}

let keypad = [
    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 9]
];

let currentButton = [1, 1];
let code = [];
for (let i = 0; splitInput.length > i; i++) {
    let currentInstructions = splitInput[i];
    for (let j = 0; currentInstructions.length > j; j++) {
        let moves = instructions[currentInstructions[j]];
        currentButton[0] += moves[0];
        if (currentButton[0] > 2) currentButton[0] = 2;
        if (0 > currentButton[0]) currentButton[0] = 0;
        currentButton[1] += moves[1];
        if (currentButton[1] > 2) currentButton[1] = 2;
        if (0 > currentButton[1]) currentButton[1] = 0;
    }

    let row = currentButton[0];
    let col = currentButton[1];
    code.push(keypad[row][col]);
}
console.log("Answer 1/2:", code.join(""));

keypad = [
    [0, 0, 1, 0, 0],
    [0, 2, 3, 4, 0],
    [5, 6, 7, 8, 9],
    [0, "A", "B", "C", 0],
    [0, 0, "D", 0, 0],
]

currentButton = [2, 0];
code = [];

for (let i = 0; splitInput.length > i; i++) {
    let currentInstructions = splitInput[i];

    let row;
    let col;

    for (let j = 0; currentInstructions.length > j; j++) {
        let moves = instructions[currentInstructions[j]];

        let newRow = currentButton[0] + moves[0];
        let newCol = currentButton[1] + moves[1];

        if (keypad[newRow]?.[newCol]) currentButton = [newRow, newCol];
    }
    row = currentButton[0];
    col = currentButton[1];
    code.push(keypad[row][col]);
}

console.log("Answer 2/2:", code.join(""));
